<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-muted: #f8fafc;
        --text: #111827;
        --muted: #5b6472;
        --border: #d8dee9;
        --accent: #2563eb;
        --accent-dark: #1d4ed8;
        --accent-soft: #dbeafe;
        --shadow: 0 24px 70px rgba(17, 24, 39, 0.12);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.18), transparent 32rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 2;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--accent);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #0f172a;
        outline-offset: 3px;
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: clamp(1rem, 4vw, 3rem);
      }

      .card {
        width: min(100%, 42rem);
        border: 1px solid rgba(216, 222, 233, 0.9);
        border-radius: 1.5rem;
        padding: clamp(1.5rem, 5vw, 3rem);
        background: rgba(255, 255, 255, 0.9);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-dark);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.3rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 33rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.5rem;
      }

      .form-field {
        margin: 0;
        border: 0;
        padding: 0;
      }

      legend {
        margin-bottom: 0.5rem;
        padding: 0;
        font-size: 1.125rem;
        font-weight: 800;
      }

      .required-note,
      .field-help {
        color: var(--muted);
      }

      .required-note {
        margin: 0 0 1rem;
        font-size: 0.9rem;
      }

      .field-help {
        margin: 0 0 1rem;
        line-height: 1.5;
      }

      .required-marker {
        color: var(--accent-dark);
        font-weight: 900;
      }

      .radio-options {
        display: grid;
        gap: 0.85rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        min-height: 3.5rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        padding: 0.9rem 1rem;
        background: var(--surface-muted);
        transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
      }

      .radio-option:has(input:checked) {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 0 0 1px var(--accent);
      }

      .radio-option:has(input:focus-visible) {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      input[type="radio"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      label {
        color: var(--text);
        font-weight: 700;
        cursor: pointer;
      }

      .button-row {
        display: flex;
        justify-content: flex-end;
      }

      button {
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        padding: 0.85rem 1.35rem;
        color: #ffffff;
        background: var(--accent);
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--accent-dark);
      }

      button:focus-visible {
        outline: 3px solid #0f172a;
        outline-offset: 3px;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .radio-option,
        button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .radio-option:has(input:checked) {
          outline: 2px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="root"></div>
    </main>

    <script>
      const notificationOptions = [
        { id: "notification-email", label: "Email", value: "email" },
        { id: "notification-sms", label: "SMS", value: "sms" },
        { id: "notification-push", label: "Push Notifications", value: "push" }
      ];

      function RadioOption({ id, label, name, value }) {
        return `
          <div class="radio-option">
            <input id="${id}" type="radio" name="${name}" value="${value}" required>
            <label for="${id}">${label}</label>
          </div>
        `;
      }

      function NotificationPreferenceForm() {
        const optionsMarkup = notificationOptions
          .map((option) => RadioOption({ ...option, name: "notificationPreference" }))
          .join("");

        return `
          <form action="#" method="post">
            <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
            <fieldset class="form-field" aria-describedby="notification-help">
              <legend>
                How do you prefer to receive notifications?
                <span class="required-marker" aria-hidden="true">*</span>
              </legend>
              <p id="notification-help" class="field-help">Choose one notification channel for important product updates.</p>
              <div class="radio-options">
                ${optionsMarkup}
              </div>
            </fieldset>
            <div class="button-row">
              <button type="submit">Save preference</button>
            </div>
          </form>
        `;
      }

      function App() {
        return `
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Account settings</p>
            <h1 id="page-title">Stay in the loop</h1>
            <p class="intro">Tell us how to reach you so the right updates arrive in the right place.</p>
            ${NotificationPreferenceForm()}
          </section>
        `;
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
